props.description:
Data is copied here from the Approved Workcenter Record for the process, if the "useGlobalRates" is true on the process - then the values are copied from the workcenter itself.
,
    "scheduledStartAt": {
      "_isNull":false
    },
    "estimatedTime": {
      "_isNull":false
    },

data.__transform:
(
  $instructions := [
    {"type": "Workcenter", "description": data.workcenter.description},
    {"type": "Workorder", "description": data.workorder.description},
    {"type": "Workorder Process", "description": data.workOrderProcess.description},
    {"type": "Product", "description": data.product.description},
    {"type": "Process", "description": data.productStrategyProcess.process.description}
    {"type": "Product Strategy", "description": data.productStrategyProcess.productStrategy.description},
    {"type": "Product Strategy Process", "description": data.productStrategyProcess.description}
  ];

  $join(
    [ "#### " & data.workOrder.number & "-" & data.product.code & "-" & data.workOrderProcess.process.code, $instructions.( description? "* **" & type & "**: " & description )],
    "\n"
  )

)

query.query:
query ($filter: EmployeeWhereInput, $now: Date!, $certificationId: String!){
 data: employee (where: $filter){
    edges {
      node {
        id
        fullName
        firstName
        lastName
        active
        generic
        position

        employeeCertifications(
          where:{
						active:{ _eq: true }
            certificationId:{ _eq: $certificationId}
            _and:[
              {
                _or:[
                  { effectiveAt: { _lte: $now}},
                  { effectiveAt: { _isNull: true}}
                ]
              },
              {
                _or:[
                  { expirationAt: { _gt: $now}},
                  { expirationAt: { _isNull: true}}
                ]
              }
            ]
          }
        ) {
          edges {
            node {
              id
              number
              level
              description
              message
              certificationId
            }
          }
        }
      }
    }
  }
}
